<!-- wp:paragraph {"className":"is-style-paragraph-2","style":{"spacing":{"margin":{"top":"24px"}}}} -->
<p class="is-style-paragraph-2" style="margin-top:24px">As part of National Sleep Foundation’s (NSF) sleep health mission, a stated goal is that sleep science and insights are rapidly incorporated into accessible health products and services.</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"className":"is-style-paragraph-2","style":{"spacing":{"margin":{"top":"24px"}}}} -->
<p class="is-style-paragraph-2" style="margin-top:24px">Sleep technology has incredible potential to improve consumers’ sleep and their health. NSF is committed to making science-based sleep technology more accessible and convenient so anyone and everyone can be their Best Slept Self®.</p>
<!-- /wp:paragraph -->
</div>
<!-- /wp:group -->
<!-- wp:group {"style":{"spacing":{"margin":{"top":"58.3px"},"blockGap":"0"}},"layout":{"type":"constrained","contentSize":"600px","justifyContent":"left"}} -->
